using FluentValidation;namespace SchoolERP.Application.Features.Subjects;public sealed class CreateSubjectRequestValidator:AbstractValidator<CreateSubjectRequest>{public CreateSubjectRequestValidator(){RuleFor(x=>x.AcademicYearId).NotEmpty();RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.Type).IsInEnum();RuleFor(x=>x.Category).IsInEnum().When(x=>x.Category.HasValue);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.CreditHours).GreaterThan(0).LessThanOrEqualTo(100).When(x=>x.CreditHours.HasValue);RuleFor(x=>x.WeeklyPeriods).InclusiveBetween(1,50).When(x=>x.WeeklyPeriods.HasValue);RuleFor(x=>x.Description).MaximumLength(1000);}}public sealed class UpdateSubjectRequestValidator:AbstractValidator<UpdateSubjectRequest>{public UpdateSubjectRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.Type).IsInEnum();RuleFor(x=>x.Category).IsInEnum().When(x=>x.Category.HasValue);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.CreditHours).GreaterThan(0).LessThanOrEqualTo(100).When(x=>x.CreditHours.HasValue);RuleFor(x=>x.WeeklyPeriods).InclusiveBetween(1,50).When(x=>x.WeeklyPeriods.HasValue);RuleFor(x=>x.Description).MaximumLength(1000);}}public sealed class ChangeSubjectCodeRequestValidator:AbstractValidator<ChangeSubjectCodeRequest>{public ChangeSubjectCodeRequestValidator()=>RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");}public sealed class SetClassSubjectsRequestValidator:AbstractValidator<SetClassSubjectsRequest>{public SetClassSubjectsRequestValidator(){RuleFor(x=>x.Items).NotNull().Must(x=>x.Select(i=>i.SubjectId).Distinct().Count()==x.Count).WithMessage("Duplicate SubjectId values are not allowed.");RuleForEach(x=>x.Items).ChildRules(i=>{i.RuleFor(x=>x.SubjectId).NotEmpty();i.RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);});}}
